export default function SheetVisionTechStack() {
  return (
    <div className="max-w-6xl mx-auto flex flex-col justify-center items-center mt-10 pb-25">
      {/* Section Header */}
      <div className="text-center mb-8 sm:mb-12">
        <h2 className="text-3xl sm:text-4xl md:text-5xl font-bold text-[#fefffe] mb-3 sm:mb-4">
          Tech Stack
        </h2>
        <div className="w-20 sm:w-24 h-1 bg-gradient-to-r from-[#ed1313] to-[#ff2a2a] mx-auto rounded-full" />
        <p className="mt-4 sm:mt-6 text-base sm:text-lg text-[#b8b8b8] max-w-2xl mx-auto">
          Built with modern technologies for optimal performance and user
          experience
        </p>
      </div>

      {/* Tech Grid */}
      <div className="gap-4 sm:gap-6 flex sm:flex-col md:flex-row">
        {technologies.map((tech, index) => (
          <motion.div
            key={tech.name}
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.5, delay: index * 0.1 }}
            whileHover={{ y: -8, scale: 1.05 }}
            className="group relative"
          >
            {/* Card */}
            <div className="relative bg-[#2b1111] border border-[#5c2020] rounded-xl p-4 sm:p-6 transition-all duration-300 hover:border-[#ed1313] hover:shadow-lg hover:shadow-[#ed1313]/20">
              {/* Glow effect on hover */}
              <div className="absolute inset-0 rounded-xl bg-gradient-to-br from-[#ed1313]/0 to-[#ed1313]/0 group-hover:from-[#ed1313]/5 group-hover:to-[#ff2a2a]/5 transition-all duration-300" />

              {/* Logo */}
              <div className="relative w-12 h-12 sm:w-16 sm:h-16 mx-auto mb-3 sm:mb-4 transition-transform duration-300 group-hover:scale-110">
                {tech.logo}
              </div>

              {/* Tech Name */}
              <h3 className="relative text-center text-sm sm:text-base font-semibold text-[#fefffe] transition-colors duration-300 group-hover:text-[#ff2a2a]">
                {tech.name}
              </h3>

              {/* Ambient glow */}
              <div className="absolute inset-0 -z-10 rounded-xl bg-[#ed1313]/0 blur-xl transition-all duration-300 group-hover:bg-[#ed1313]/10" />
            </div>
          </motion.div>
        ))}
      </div>
    </div>
  );
}
